mapper.select:
/* RoleGroupMapper.findByRoleCode */
SELECT role_code, role_name, level, description, created_by, created_at
FROM role_group
WHERE role_code = #{roleCode}

/* RoleGroupMapper.findLevelByRoleCode */
SELECT level
FROM role_group
WHERE role_code = #{roleCode}

mapper.insert:
/* RoleGroupMapper.upsertRole */
INSERT INTO role_group (
    role_code, role_name, level, description, created_by, created_at
)
VALUES (
    #{roleCode}, #{roleName}, #{level}, #{description}, #{createdBy}, #{createdAt}
)
ON DUPLICATE KEY UPDATE
    role_name = VALUES(role_name),
    level = VALUES(level),
    description = VALUES(description)

mapper.select:
/* RoleGroupMapper.findRolesPaged */
SELECT role_code, role_name, level, description, created_by, created_at
FROM role_group
ORDER BY level DESC
LIMIT #{limit} OFFSET #{offset}
